svg.script:


console.log("Scalio started");


const gamesLayer =
document.getElementById("games");

const categoryLayer =
document.getElementById("categories");


let games = [];

let gameOffsetY = 0;



const JSON_URL =
"https://raw.githubusercontent.com/CowGoMoo357/htmlgamesrepos/main/games.json";



fetch(JSON_URL)

.then(r => r.json())

.then(data => {

    console.log("JSON:", data);

    games = data.games;

    createCategories();

    displayGames(games);

})

.catch(error => {

    console.error(
        "Games failed:",
        error
    );

});





function createCategories(){


    const categories = [
        "All",
        ...new Set(
            games.map(
                g=>g.category
            )
        )
    ];



    categories.forEach(
    (cat,index)=>{


        const ns =
        "http://www.w3.org/2000/svg";


        let y =
        260 + index * 55;



        let button =
        document.createElementNS(
            ns,
            "g"
        );


        let rect =
        document.createElementNS(
            ns,
            "rect"
        );


        rect.setAttribute("x","60");
        rect.setAttribute("y",y-30);
        rect.setAttribute("width","170");
        rect.setAttribute("height","40");
        rect.setAttribute("rx","20");
        rect.setAttribute("fill","#ffffff15");



        let text =
        document.createElementNS(
            ns,
            "text"
        );


        text.setAttribute("x","145");
        text.setAttribute("y",y);
        text.setAttribute("fill","white");
        text.setAttribute("text-anchor","middle");
        text.setAttribute("font-size","16");


        text.textContent = cat;



        button.appendChild(rect);
        button.appendChild(text);



        button.onclick = ()=>{


            gameOffsetY = 0;


            if(cat === "All"){

                displayGames(games);

            }

            else{

                displayGames(
                    games.filter(
                        g=>g.category===cat
                    )
                );

            }


        };



        categoryLayer.appendChild(button);


    });


}







function displayGames(list){


    gamesLayer.replaceChildren();


    gamesLayer.setAttribute(
        "transform",
        `translate(0 ${gameOffsetY})`
    );



    list.forEach(
    (game,index)=>{


        const ns =
        "http://www.w3.org/2000/svg";



        let group =
        document.createElementNS(
            ns,
            "g"
        );



        // 4 columns

        let x =
        330 +
        (index % 4) * 220;



        let y =
        250 +
        Math.floor(index / 4) * 240;





        let card =
        document.createElementNS(
            ns,
            "rect"
        );


        card.setAttribute("x",x);
        card.setAttribute("y",y);
        card.setAttribute("width","200");
        card.setAttribute("height","210");
        card.setAttribute("rx","28");
        card.setAttribute("fill","#ffffff15");


        group.appendChild(card);





        // icon

        let icon =
        document.createElementNS(
            ns,
            "image"
        );


        icon.setAttribute(
            "x",
            x+60
        );

        icon.setAttribute(
            "y",
            y+20
        );

        icon.setAttribute(
            "width",
            "80"
        );

        icon.setAttribute(
            "height",
            "80"
        );


        icon.setAttribute(
            "href",
            game.icon
        );


        group.appendChild(icon);






        // title

        let title =
        document.createElementNS(
            ns,
            "text"
        );


        title.setAttribute("x",x+100);
        title.setAttribute("y",y+135);
        title.setAttribute("fill","white");
        title.setAttribute("font-size","18");
        title.setAttribute("text-anchor","middle");


        title.textContent =
        game.name;


        group.appendChild(title);






        // category

        let category =
        document.createElementNS(
            ns,
            "text"
        );


        category.setAttribute("x",x+100);
        category.setAttribute("y",y+165);
        category.setAttribute("fill","#aaa");
        category.setAttribute("font-size","14");
        category.setAttribute("text-anchor","middle");


        category.textContent =
        game.category;


        group.appendChild(category);






        group.onclick = ()=>{

            launchGame(game);

        };



        gamesLayer.appendChild(group);


    });


}







function scrollGames(amount){


    gameOffsetY += amount;



    if(gameOffsetY > 0){

        gameOffsetY = 0;

    }



    // change this if you add more games

    if(gameOffsetY < -3000){

        gameOffsetY = -3000;

    }



    gamesLayer.setAttribute(
        "transform",
        `translate(0 ${gameOffsetY})`
    );


}






document.addEventListener(
"wheel",
(event)=>{


    scrollGames(
        -event.deltaY
    );


});







async function launchGame(game){


    const html =
    await fetch(game.url)
    .then(r=>r.text());



    const old =
    document.getElementById(
        "gameWindow"
    );


    if(old)
        old.remove();



    const fo =
    document.createElementNS(
        "http://www.w3.org/2000/svg",
        "foreignObject"
    );


    fo.setAttribute(
        "id",
        "gameWindow"
    );


    fo.setAttribute("x","300");
    fo.setAttribute("y","120");
    fo.setAttribute("width","850");
    fo.setAttribute("height","550");



    const div =
    document.createElementNS(
        "http://www.w3.org/1999/xhtml",
        "div"
    );


    div.style.width="100%";
    div.style.height="100%";


    div.innerHTML = html;



    fo.appendChild(div);


    document.documentElement.appendChild(fo);




    div.querySelectorAll("script")
    .forEach(oldScript=>{


        let script =
        document.createElement(
            "script"
        );


        script.textContent =
        oldScript.textContent;


        oldScript.replaceWith(script);


    });


}
